public.ai_skill_candidate_guard().source:
DECLARE o public.ai_pi_operations; s public.ai_pi_sessions;
BEGIN
 SELECT * INTO o FROM public.ai_pi_operations WHERE id=NEW.operation_id;
 IF o.id IS NULL THEN RAISE EXCEPTION 'ai_skill_candidate_operation_missing'; END IF;
 SELECT * INTO s FROM public.ai_pi_sessions WHERE id=o.session_id;
 IF s.id IS NULL OR s.owner_email<>NEW.owner_email
   THEN RAISE EXCEPTION 'ai_skill_candidate_owner'; END IF;
 -- A candidate distils a finished run. Only a succeeded operation produced a
 -- report; distilling an unknown or failed run would cite a result that is not
 -- established.
 IF o.status<>'succeeded' THEN RAISE EXCEPTION 'ai_skill_candidate_run_not_succeeded'; END IF;
 IF TG_OP='INSERT' AND (NEW.status<>'draft' OR NEW.version<>1
   OR NEW.reviewed_by<>'' OR NEW.reviewed_at IS NOT NULL)
   THEN RAISE EXCEPTION 'ai_skill_candidate_initial_state'; END IF;
 IF TG_OP='UPDATE' THEN
  -- Approval binds the content that was reviewed. Since the identity guard
  -- freezes content_digest, this states the rule the application also keeps:
  -- an approved row cannot be edited back into review and keep its approval.
  IF NEW.status IN ('approved','rejected') AND (NEW.reviewed_by='' OR NEW.reviewed_at IS NULL)
    THEN RAISE EXCEPTION 'ai_skill_candidate_review_identity_required'; END IF;
  IF OLD.status IN ('approved','rejected') AND NEW.status IN ('draft','in_review')
    THEN RAISE EXCEPTION 'ai_skill_candidate_no_reopen'; END IF;
  IF NEW.version<=OLD.version THEN RAISE EXCEPTION 'ai_skill_candidate_version'; END IF;
 END IF;
 RETURN NEW;
END

