public.ai_task_feedback_guard().source:
DECLARE o public.ai_pi_operations; s public.ai_pi_sessions;
BEGIN
 SELECT * INTO o FROM public.ai_pi_operations WHERE id=NEW.operation_id;
 IF o.id IS NULL THEN RAISE EXCEPTION 'ai_task_feedback_operation_missing'; END IF;
 SELECT * INTO s FROM public.ai_pi_sessions WHERE id=o.session_id;
 -- A correction belongs to the generation that produced the report. After a
 -- scope change the environment advances its generation, and an older
 -- correction must not read as applying to the new one.
 IF s.id IS NULL OR o.generation<>NEW.generation OR s.owner_email<>NEW.owner_email
   THEN RAISE EXCEPTION 'ai_task_feedback_binding'; END IF;
 -- Corrections describe a finished task. Attaching one to a task still in
 -- flight would let it be cited before the report it corrects exists.
 IF o.status NOT IN ('succeeded','failed','canceled','unknown','frozen')
   THEN RAISE EXCEPTION 'ai_task_feedback_operation_not_settled'; END IF;
 IF TG_OP='INSERT' AND (NEW.status<>'confirmed' OR NEW.version<>1)
   THEN RAISE EXCEPTION 'ai_task_feedback_initial_state'; END IF;
 -- Only a human confirmation counts as confirmed. A model proposal stays a
 -- proposal, so candidate distillation cannot cite it as settled.
 IF NEW.source='model_suggested' AND NEW.status='confirmed'
   THEN RAISE EXCEPTION 'ai_task_feedback_model_cannot_confirm'; END IF;
 RETURN NEW;
END

